# --- the secret canaries (RD-170-06): what takes, stores, logs, seals or hands back a credential.
# Added to whatever the rows above select; they still decide the rest of each path.
^crates/rd-api(-[a-z]+)?/src/(config_handlers|config_fields|remote_handlers|object_storage_(handlers|fields)|notify_(handlers|service)|backup_[a-z_]+|settings_backup[a-z_]*|diagnostics_[a-z_]+|captcha_handlers|api_tokens|auth_profile_handlers|usenet_handlers|login_handlers|password_handlers|event_stream)\.rs$   + canaries
^crates/(rd-secrets|rd-diagnostics|rd-backup|rd-notify|rd-object-storage|rd-ftp)/src/        + canaries

# --- rd-core, by domain module ----------------------------------------------------------------
# failpoint.rs compiles to nothing without its feature; the crash matrix is its test.
# recovery-matrix.md is the table rd-core's own library test compares with the registry.
^crates/rd-core/src/failpoint\.rs$                                                        -
^crates/rd-core/recovery-matrix\.md$                                                      -
^crates/rd-core/tests/                                                                    -
^crates/rd-core/src/audit\.rs$                                                            audit data_reset api_tokens public_surface step_up mcp
^crates/rd-core/src/(auth_flow|auth_profile|cookie_file)\.rs$                             auth_profiles media_cookie_profile browser_session capture_intake mcp
^crates/rd-core/src/session\.rs$                                                          sessions auth mfa passkeys browser_session
^crates/rd-core/src/backup\.rs$                                                           full_backup backup_destinations mcp
^crates/rd-core/src/bandwidth\.rs$                                                        bandwidth mcp
^crates/rd-core/src/capture\.rs$                                                          capture_intake capture_boundary captcha event_resume browser_session auth_profiles
^crates/rd-core/src/collector\.rs$                                                        capture_intake containers container_json enqueue_cancellation indexers media_cookie_profile media_manifest mirrors nzb_paused reorder replay_consent replay_restart service_switches storage_capacity torrent api_tokens mcp
^crates/rd-core/src/source_set\.rs$                                                       source_sets mirrors mcp
